sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || !newValue) {
        return;
    }

    // Obtém a data e hora atual sem a parte do tempo (para garantir uma comparação correta)
    var currentDate = new Date();
    currentDate.setHours(0, 0, 0, 0); // Zera horas, minutos, segundos e milissegundos para comparar apenas a data

    // Converte o valor selecionado para um objeto Date corretamente
    var selectedDate = new Date(newValue);

    // Verifica se a data selecionada é anterior à data atual
    if (selectedDate < currentDate) {
        alert('A data da solicitação não pode ser menor que a data atual.');
        g_form.setValue('data_e_hora_da_solicitacao', ''); // Limpa o campo inválido
    }
}
